const npcMed=()=>{const rk=$('#region').value==='any'?R(Object.keys(MED)):$('#region').value,r=MED[rk];let g=$('#gender').value;if(g==='a')g=R(['m','f']);
return{n:R(r[g])+' '+r.s(g),s:$('#hook').value==='1'?`${r.l} ${R(MJOBS)}, ${R(QUIRKS)}`:r.l}};

let cat='npc', results=[], kept=store.get('kept',[]);
$('#style').value=store.get('style','fantasy');$('#region').innerHTML='<option value="any">Any region</option>'+Object.entries(MED).map(([k,r])=>`<option value="${k}">${r.l}</option>`).join('');
$('#race').innerHTML='<option value="any">Any ancestry</option>'+Object.entries(RACES).map(([k,r])=>`<option value="${k}">${r.l}</option>`).join('');
const renderCats=()=>{$('#cats').innerHTML=Object.entries(CATS).map(([k,c])=>`<button class="chip${k===cat?' on':''}" data-c="${k}">${c.l}</button>`).join('');const med=$('#style').value==='medieval',np=cat==='npc';$('#o-race').style.display=np&&!med?'':'none';$('#o-region').style.display=np&&med?'':'none';$('#o-gender').style.display=$('#o-hook').style.display=np?'':'none';$('#roll').textContent=`Roll 12 ${cat==='npc'?'NPCs':CATS[cat].l.toLowerCase()}`};
const npc=()=>{const rk=$('#race').value==='any'?R(Object.keys(RACES)):$('#race').value,r=RACES[rk];let g=$('#gender').value;if(g==='a')g=R(['m','f']);
const first=R(r[g][0])+R(r[g][1]),last=R(r.s[0])+R(r.s[1]);return{n:first+' '+last,s:$('#hook').value==='1'?`${r.l} ${R(JOBS)}, ${R(QUIRKS)}`:r.l}};
const roll=()=>{const seen=new Set();results=[];let guard=0;while(results.length<12&&guard++<200){const med=$('#style').value==='medieval';const o=cat==='npc'?(med?npcMed():npc()):{n:(med?MCATS[cat]:CATS[cat].f)(),s:''};if(!seen.has(o.n)){seen.add(o.n);results.push(o)}}renderRes()};
const isKept=n=>kept.some(k=>k.n===n);
const renderRes=()=>{$('#res').innerHTML=results.map((o,i)=>`<div class="nm"><div><b>${esc(o.n)}</b>${o.s?`<small>${esc(o.s)}</small>`:''}</div><button class="ic" data-cp="${i}" aria-label="Copy ${esc(o.n)}">${ICON.copy}</button><button class="ic${isKept(o.n)?' kept':''}" data-kp="${i}" aria-label="Keep ${esc(o.n)}">${ICON.star}</button></div>`).join('')};
const renderKept=()=>{$('#keptEmpty').style.display=kept.length?'none':'';$('#kept').innerHTML=kept.map((k,i)=>`<div><span><b>${esc(k.n)}</b><br><small class="muted">${esc(k.c)}</small></span><button class="btn sm x" data-rk="${i}" aria-label="Remove">✕</button></div>`).join('');store.set('kept',kept)};
$('#cats').onclick=e=>{const b=e.target.closest('[data-c]');if(!b)return;cat=b.dataset.c;renderCats();roll()};
['race','region','gender','hook'].forEach(id=>$('#'+id).onchange=roll);
$('#style').onchange=()=>{store.set('style',$('#style').value);renderCats();roll()};
$('#roll').onclick=roll;
$('#res').onclick=e=>{const c=e.target.closest('[data-cp]'),k=e.target.closest('[data-kp]');
if(c)copy(results[c.dataset.cp].n);
if(k){const o=results[k.dataset.kp];if(isKept(o.n))kept=kept.filter(x=>x.n!==o.n);else kept.unshift({n:o.n,c:CATS[cat].l.replace(/ies$/,'y').replace(/s$/,'')+(o.s?' · '+o.s:'')});renderKept();renderRes()}};
$('#kept').onclick=e=>{const b=e.target.closest('[data-rk]');if(b){kept.splice(+b.dataset.rk,1);renderKept();renderRes()}};
$('#copyall').onclick=()=>copy(results.map(o=>o.n+(o.s?' — '+o.s:'')).join('\n'),'All names copied');
$('#copykept').onclick=()=>copy(kept.map(k=>k.n+' ('+k.c+')').join('\n'),'Kept names copied');
$('#clearkept').onclick=()=>{kept=[];renderKept();renderRes()};

