const blank=()=>({name:'New Monster',size:'Medium',type:'Monstrosity',tag:'',align:'Unaligned',ac:12,acNote:'',hd:4,hdie:8,speed:'30 ft.',ab:[10,10,10,10,10,10],saves:[],skills:[],expert:[],vuln:'',res:'',imm:'',cimm:'',senses:'',langs:'—',cr:'1',legN:0,traits:[],actions:[],bonus:[],reactions:[],legendary:[]});
let M=store.get('draft',null)||JSON.parse(JSON.stringify(SAMPLE)), lib=store.get('lib',[]);
const hp=m=>{const c=mod(m.ab[2]);const n=+m.hd||1,d=+m.hdie;return{avg:m.hpx??Math.max(1,Math.floor(n*(d+1)/2)+n*c),str:`${n}d${d}${c?(c>0?' + ':' − ')+Math.abs(n*c):''}`}};
const atkText=(a,m)=>{const pb=PB(m.cr),am=mod(m.ab[+a.ab]),mt=(a.d||'1d6').match(/(\d+)d(\d+)/);const n=mt?+mt[1]:1,d=mt?+mt[2]:6;const avg=Math.max(1,Math.floor(n*(d+1)/2)+am);
return`${a.k==='m'?'Melee':'Ranged'} Weapon Attack: ${sg(am+pb)} to hit, ${a.k==='m'?'reach':'range'} ${a.rg}, one target. Hit: ${avg} (${n}d${d}${am?(am>0?' + ':' − ')+Math.abs(am):''}) ${a.t} damage.`};
const itemName=i=>i.atk?i.atk.n:i.n, itemDesc=(i,m)=>i.atk?atkText(i.atk,m):i.d;
const skillStr=m=>m.skills.map(i=>{const [n,a]=SK[i];return`${n} ${sg(mod(m.ab[a])+PB(m.cr)*(m.expert.includes(i)?2:1))}`}).join(', ');
const passive=m=>{const i=11;return 10+mod(m.ab[4])+(m.skills.includes(i)?PB(m.cr)*(m.expert.includes(i)?2:1):0)};
const block=(title,arr,m,intro)=>arr.length?`<h4>${title}</h4>${intro?`<p>${esc(intro)}</p>`:''}${arr.map(i=>`<p class="ac"><b>${esc(itemName(i))}.</b> ${esc(itemDesc(i,m)).replace(/\n/g,'<br>')}</p>`).join('')}`:'';
const line=(k,v)=>v?`<p class="p"><b>${k}</b> ${esc(v)}</p>`:'';
const sbHTML=m=>{const h=hp(m);return`<h3>${esc(m.name)}</h3><div class="sub">${esc(m.size)} ${esc(m.type).toLowerCase()}${m.tag?' ('+esc(m.tag)+')':''}, ${esc(m.align).toLowerCase()}</div><hr>
${line('Armor Class',m.ac+(m.acNote?` (${m.acNote})`:''))}${line('Hit Points',`${h.avg} (${h.str})`)}${line('Speed',m.speed)}<hr>
<div class="ab">${AB.map((a,i)=>`<div><b>${a}</b>${m.ab[i]} (${sg(mod(m.ab[i]))})</div>`).join('')}</div><hr>
${line('Saving Throws',m.saves.map(i=>`${AB[i][0]+AB[i].slice(1).toLowerCase()} ${sg(mod(m.ab[i])+PB(m.cr))}`).join(', '))}${line('Skills',skillStr(m))}
${line('Damage Vulnerabilities',m.vuln)}${line('Damage Resistances',m.res)}${line('Damage Immunities',m.imm)}${line('Condition Immunities',m.cimm)}
${line('Senses',(m.senses?m.senses+', ':'')+'passive Perception '+passive(m))}${line('Languages',m.langs||'—')}
<p class="p"><b>Challenge</b> ${m.cr} (${XP[m.cr].toLocaleString()} XP) &nbsp; <b>Proficiency Bonus</b> +${PB(m.cr)}</p><hr>
${m.traits.map(i=>`<p class="ac"><b>${esc(i.n)}.</b> ${esc(i.d).replace(/\n/g,'<br>')}</p>`).join('')}
${block('Actions',m.actions,m)}${block('Bonus Actions',m.bonus,m)}${block('Reactions',m.reactions,m)}
${block('Legendary Actions',m.legendary,m,m.legN?`The ${esc(m.name.replace(/^the /i,'')).toLowerCase()} can take ${m.legN} legendary actions, choosing from the options below. Only one legendary action can be used at a time and only at the end of another creature's turn. Spent legendary actions are regained at the start of each turn.`:'')}`};
const renderSB=()=>{$('#sb').innerHTML=sbHTML(M);store.set('draft',M)};
const renderAbil=()=>{$('#abil').innerHTML=AB.map((a,i)=>`<label>${a}<input type="number" min="1" max="30" data-ab="${i}" value="${M.ab[i]}" aria-label="${a} score"><span id="mod${i}">${sg(mod(M.ab[i]))}</span></label>`).join('')};
const renderChecks=()=>{$('#saves').innerHTML='<b style="width:100%;font-size:14px">Saving throws</b>'+AB.map((a,i)=>`<label><input type="checkbox" data-sv="${i}" ${M.saves.includes(i)?'checked':''}>${a}</label>`).join('');
$('#skills').innerHTML='<b style="width:100%;font-size:14px">Proficient skills</b>'+SK.map((s,i)=>`<label><input type="checkbox" data-sk="${i}" ${M.skills.includes(i)?'checked':''}>${s[0]}</label>`).join('');
$('#expert').innerHTML=M.skills.length?'<b style="width:100%;font-size:14px">Expertise</b>'+M.skills.map(i=>`<label><input type="checkbox" data-ex="${i}" ${M.expert.includes(i)?'checked':''}>${SK[i][0]}</label>`).join(''):''};
const LISTS=['traits','actions','bonus','reactions','legendary'];
const renderLists=()=>LISTS.forEach(L=>{$('#L-'+L).innerHTML=M[L].map((it,i)=>it.atk?`<div class="li"><div><b>${esc(it.atk.n)}</b> <small class="muted">auto attack · ${esc(atkText(it.atk,M))}</small></div><button class="btn sm x" data-del="${L}:${i}" aria-label="Delete">✕</button></div>`:
`<div class="li"><input data-li="${L}:${i}:n" value="${esc(it.n)}" aria-label="Name"><button class="btn sm x" data-del="${L}:${i}" aria-label="Delete">✕</button><textarea data-li="${L}:${i}:d" aria-label="Description">${esc(it.d)}</textarea></div>`).join('')});
const loadForm=()=>{document.querySelectorAll('#mform [data-k]').forEach(el=>{const v=M[el.dataset.k]??'';if(el.tagName==='SELECT'&&v!==''&&![...el.options].some(o=>o.value===String(v)))el.add(new Option(v,v));el.value=v});renderAbil();renderChecks();renderLists();renderSB()};
const fm=$('#mform');
fm.addEventListener('input',e=>{const t=e.target;
if(t.dataset.k){M[t.dataset.k]=t.type==='number'?+t.value:t.value;if(t.dataset.k==='hd'||t.dataset.k==='hdie')delete M.hpx;if(t.dataset.k==='cr')renderLists()}
else if(t.dataset.ab){if(t.dataset.ab==='2')delete M.hpx;M.ab[+t.dataset.ab]=Math.max(1,Math.min(30,+t.value||1));$('#mod'+t.dataset.ab).textContent=sg(mod(M.ab[+t.dataset.ab]));renderLists()}
else if(t.dataset.li){const [L,i,f]=t.dataset.li.split(':');M[L][+i][f]=t.value}
else return;renderSB()});
fm.addEventListener('change',e=>{const t=e.target,tog=(arr,v)=>t.checked?(arr.includes(v)||arr.push(v)):arr.splice(arr.indexOf(v),1);
if(t.dataset.sv)tog(M.saves,+t.dataset.sv);else if(t.dataset.sk){tog(M.skills,+t.dataset.sk);if(!t.checked)M.expert=M.expert.filter(x=>M.skills.includes(x));M.skills.sort((a,b)=>a-b);renderChecks()}else if(t.dataset.ex)tog(M.expert,+t.dataset.ex);else if(t.dataset.k){M[t.dataset.k]=t.value;if(t.dataset.k==='hdie')delete M.hpx;if(t.dataset.k==='cr')renderLists()}else return;renderSB()});
fm.addEventListener('click',e=>{const a=e.target.closest('[data-add]'),d=e.target.closest('[data-del]');
if(a){M[a.dataset.add].push({n:'New '+a.textContent.replace('+ ','').toLowerCase(),d:''});renderLists();renderSB()}
if(d){const [L,i]=d.dataset.del.split(':');M[L].splice(+i,1);renderLists();renderSB()}});
$('#addatk').onclick=()=>{M.actions.push({atk:{n:$('#a-n').value||'Attack',k:$('#a-k').value,ab:$('#a-ab').value,rg:$('#a-rg').value||'5 ft.',d:$('#a-d').value||'1d6',t:$('#a-t').value||'bludgeoning'}});renderLists();renderSB();toast('Attack added')};
const toText=m=>{const h=hp(m),L=[m.name.toUpperCase(),`${m.size} ${m.type.toLowerCase()}${m.tag?' ('+m.tag+')':''}, ${m.align.toLowerCase()}`,'',`Armor Class ${m.ac}${m.acNote?' ('+m.acNote+')':''}`,`Hit Points ${h.avg} (${h.str})`,`Speed ${m.speed}`,'',AB.map((a,i)=>`${a} ${m.ab[i]} (${sg(mod(m.ab[i]))})`).join('  '),''];
if(m.saves.length)L.push('Saving Throws '+m.saves.map(i=>`${AB[i]} ${sg(mod(m.ab[i])+PB(m.cr))}`).join(', '));if(m.skills.length)L.push('Skills '+skillStr(m));
[['Damage Vulnerabilities',m.vuln],['Damage Resistances',m.res],['Damage Immunities',m.imm],['Condition Immunities',m.cimm]].forEach(([k,v])=>v&&L.push(k+' '+v));
L.push('Senses '+(m.senses?m.senses+', ':'')+'passive Perception '+passive(m),'Languages '+(m.langs||'—'),`Challenge ${m.cr} (${XP[m.cr].toLocaleString()} XP)  Proficiency Bonus +${PB(m.cr)}`,'');
m.traits.forEach(i=>L.push(`${i.n}. ${i.d}`));[['ACTIONS','actions'],['BONUS ACTIONS','bonus'],['REACTIONS','reactions'],['LEGENDARY ACTIONS','legendary']].forEach(([t,k])=>{if(m[k].length){L.push('',t);m[k].forEach(i=>L.push(`${itemName(i)}. ${itemDesc(i,m)}`))}});return L.join('\n')};
$('#mcopy').onclick=()=>copy(toText(M),'Stat block copied');
$('#mjson').onclick=()=>copy(JSON.stringify(M),'JSON copied');
$('#mnew').onclick=()=>{M=blank();$('#saveStat').textContent='';loadForm();toast('Fresh monster ready')};
$('#mimpgo').onclick=()=>{try{const o=sanitize(JSON.parse($('#mimp').value));if(!o)throw 0;M=o;loadForm();toast('Monster loaded')}catch(e){toast('That JSON could not be read')}};
const renderLib=()=>{$('#libEmpty').style.display=lib.length?'none':'';$('#lib').innerHTML=lib.map((m,i)=>`<div><span><b>${esc(m.name)}</b> <small class="muted">CR ${m.cr}</small></span><button class="btn sm" data-ld="${i}">Edit</button><button class="btn sm x" data-lx="${i}" aria-label="Delete ${esc(m.name)}">✕</button></div>`).join('');store.set('lib',lib);renderFromLib()};
$('#msave').onclick=async()=>{const i=lib.findIndex(x=>x.name===M.name);const st=$('#saveStat');st.textContent='Saving…';
const r=await shareToArchive();const c=JSON.parse(JSON.stringify(M));if(i>=0)lib[i]=c;else lib.push(c);renderLib();
st.textContent={ok:'Saved to your library and shared to the Monster Archive.',updated:'Saved. Your Monster Archive entry is updated.',none:'Saved to your library. The shared archive isn\'t set up yet.',readonly:'Saved to your library. Sign in below to share it with the League.',full:'Saved to your library. The archive is full right now.',err:'Saved to your library. Sharing failed; try again in a moment.'}[r];toast(r==='ok'||r==='updated'?'Shared to the Monster Archive':'Saved to library')};
$('#lib').onclick=e=>{const l=e.target.closest('[data-ld]'),x=e.target.closest('[data-lx]');if(l){M=JSON.parse(JSON.stringify(lib[+l.dataset.ld]));loadForm();scrollTo({top:0})}if(x){lib.splice(+x.dataset.lx,1);renderLib()}};

