const calc=()=>{store.set('enc',E);const size=E.party.reduce((s,p)=>s+p.n,0),count=E.foes.reduce((s,f)=>s+f.n,0),raw=E.foes.reduce((s,f)=>s+XP[f.cr]*f.n,0);
let th,names,xp=raw,mult=1,label,note='';
if(E.rules==='2024'){th=[0,1,2].map(j=>E.party.reduce((s,p)=>s+B24[p.l][j]*p.n,0));names=['Low','Moderate','High'];
label=raw===0?'No foes':raw<th[0]*.5?'Trivial':raw<=th[0]?'Low':raw<=th[1]?'Moderate':raw<=th[2]?'High':'Beyond High';
note={Trivial:'Barely a speed bump. Fine for flavor or a warm-up.',Low:'A few hits taken, few resources spent.',Moderate:'Real risk without luck or smart play; expect spell slots and HP to go.',High:'Could be lethal for one or more characters. Have an escape hatch.','Beyond High':'Over the High budget. Expect deaths unless the party has an edge.','No foes':'Add some monsters.'}[label]}
else{th=[0,1,2,3].map(j=>E.party.reduce((s,p)=>s+B14[p.l][j]*p.n,0));names=['Easy','Medium','Hard','Deadly'];
let idx=count<=1?0:count===2?1:count<=6?2:count<=10?3:count<=14?4:5;if(size<3)idx=Math.min(5,idx+1);else if(size>=6)idx=Math.max(0,idx-1);if(count===0)idx=0;
mult=size>=6&&count<=1?0.5:MULT[idx];xp=Math.round(raw*mult);
label=raw===0?'No foes':xp<th[0]?'Trivial':xp<th[1]?'Easy':xp<th[2]?'Medium':xp<th[3]?'Hard':'Deadly';
note={Trivial:'Below Easy. Little threat.',Easy:'Minor damage, no real danger.',Medium:'A scare or two; the party should win without losses.',Hard:'Characters may go down. A real fight.',Deadly:'Could be fatal for one or more characters.','No foes':'Add some monsters.'}[label]}
const max=Math.max(th[th.length-1]*1.25,xp*1.05,1);
$('#verdict').innerHTML=`<p class="muted" style="margin:0">This encounter is</p><div class="verdict">${label}</div><p style="margin:6px 0 0">${note}</p>
<div class="meter" role="img" aria-label="${xp} XP against thresholds"><div class="fill" style="width:${Math.min(100,xp/max*100)}%"></div>${th.map((t,i)=>`<div class="mk" style="left:${t/max*100}%"><span>${names[i]} ${t.toLocaleString()}</span></div>`).join('')}</div>
<div class="stats"><div><span class="muted">Monster XP</span><b>${raw.toLocaleString()}</b></div>${E.rules==='2014'?`<div><span class="muted">Adjusted (×${mult})</span><b>${xp.toLocaleString()}</b></div>`:''}<div><span class="muted">Party</span><b>${size} PCs</b></div><div><span class="muted">XP each</span><b>${size?Math.floor(raw/size).toLocaleString():0}</b></div></div>
<div class="bar" style="margin-top:14px"><button class="btn sm" id="enc-loot" ${count?'':'disabled'}>Roll loot for this fight</button></div>
<p class="muted" style="margin:12px 0 0">${E.rules==='2024'?'2024 DMG: total monster XP is compared to the party\'s Low / Moderate / High budget.':'2014 DMG: monster XP is multiplied by group size (adjusted for party size) and compared to Easy / Medium / Hard / Deadly thresholds.'}</p>`};
const encEl=$('#t-encounters');
encEl.addEventListener('input',e=>{const t=e.target,d=t.dataset;
if(d.pn)E.party[+d.pn].n=Math.max(1,+t.value||1);else if(d.fn)E.foes[+d.fn].name=t.value;else if(d.fq)E.foes[+d.fq].n=Math.max(1,+t.value||1);else return;calc()});
encEl.addEventListener('change',e=>{const t=e.target,d=t.dataset;if(d.pl)E.party[+d.pl].l=+t.value;else if(d.fc)E.foes[+d.fc].cr=t.value;else return;calc()});
encEl.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const d=t.dataset;
if(t.id==='enc-loot'){const n=E.party.reduce((s,p)=>s+p.n,0)||1;lootFor(n,Math.round(E.party.reduce((s,p)=>s+p.l*p.n,0)/n)||1,E.foes.reduce((s,f)=>s+f.n,0)||1);return}
if(d.rules){E.rules=d.rules;bShown=40;bOpen=null;renderBest();rollAll()}else if(d.px)E.party.splice(+d.px,1);else if(d.fx)E.foes.splice(+d.fx,1);else if(t.id==='addp')E.party.push({n:1,l:E.party[0]?.l||1});else if(t.id==='addf')E.foes.push({name:'Monster',cr:'1',n:1});else return;renderEncForm();calc()});
const renderFromLib=()=>{const all=[M,...lib.filter(m=>m.name!==M.name)];$('#fromlib').innerHTML='<option value="">Add from stat blocks…</option>'+all.map((m,i)=>`<option value="${i}">${esc(m.name)} (CR ${m.cr})</option>`).join('');$('#fromlib').dataset.src=JSON.stringify(all.map(m=>[m.name,m.cr]))};
$('#fromlib').onchange=e=>{const v=e.target.value;if(v==='')return;const [n,c]=JSON.parse(e.target.dataset.src)[+v];E.foes.push({name:n,cr:c,n:1});e.target.value='';renderEncForm();calc();toast(n+' joins the fight')};
$('#menc').onclick=()=>{E.foes.push({name:M.name,cr:M.cr,n:1});renderEncForm();calc();location.hash='#encounters';toast(M.name+' added to encounter')};
$('#m-name').addEventListener('change',renderFromLib);

/* ---------- bestiary ---------- */
let SRD={2014:[],2024:[]};try{SRD=JSON.parse($('#srd').textContent)}catch(e){}
let bShown=40,bOpen=null;
const bset=()=>{const v=$('#b-set').value;return v==='auto'||v==='all'?E.rules:v};
let ARCH=[],BL=[];
const bsource=()=>{const v=$('#b-set').value,sr=k=>SRD[k].map(m=>({m,src:k==='2024'?'SRD 2024':'SRD 2014'})),og=()=>ORIG.map(m=>({m,src:'Smiling DM Original'})),ar=()=>ARCH.map(a=>({m:a.m,src:'Archive'+(a.by?' · by '+a.by:'')}));
return v==='orig'?og():v==='arch'?ar():v==='all'?[...og(),...ar(),...sr(E.rules)]:sr(bset())};
$('#b-min').innerHTML=CRS.map(c=>`<option>${c}</option>`).join('');$('#b-max').innerHTML=CRS.map(c=>`<option${c==='30'?' selected':''}>${c}</option>`).join('');
$('#b-type').innerHTML='<option value="any">Any type</option>'+types.map(t=>`<option>${t}</option>`).join('');
$('#b-size').innerHTML='<option value="any">Any size</option>'+sizes.map(t=>`<option>${t}</option>`).join('');
const bfilter=()=>{const q=$('#b-q').value.trim().toLowerCase(),lo=crNum($('#b-min').value),hi=crNum($('#b-max').value),ty=$('#b-type').value,sz=$('#b-size').value;
BL=bsource();const L=BL.map((x,i)=>({m:x.m,src:x.src,i})).filter(({m})=>(!q||(m.name+' '+m.type+' '+(m.tag||'')).toLowerCase().includes(q))&&crNum(m.cr)>=lo&&crNum(m.cr)<=hi&&(ty==='any'||m.type===ty)&&(sz==='any'||m.size===sz));
if($('#b-sort').value==='cr')L.sort((a,b)=>crNum(a.m.cr)-crNum(b.m.cr)||a.m.name.localeCompare(b.m.name));return L};
const renderBest=()=>{const L=bfilter(),v=$('#b-set').value;
$('#bsrc').textContent=`${BL.length} monsters in ${({all:'everything: Smiling DM Originals, the Monster Archive and the '+(E.rules==='2024'?'2024':'2014')+' SRD',auto:'the '+(E.rules==='2024'?'2024':'2014')+' SRD','2024':'the 2024 SRD 5.2.1','2014':'the 2014 SRD 5.1',orig:'Smiling DM Originals',arch:'the Monster Archive'})[v]}. Add them to the fight, view the full stat block, or open an editable copy.`;
$('#bcount').textContent=L.length?`${L.length} match${L.length===1?'':'es'}`:'No monsters match. Try widening the CR range or clearing the search.';
$('#blist').innerHTML=L.slice(0,bShown).map(({m,i,src})=>`<div class="br"><div><b>${esc(m.name)}</b><small>${esc(src)} · ${esc(m.size)} ${esc(m.type).toLowerCase()} · AC ${m.ac} · HP ${hp({...{ab:[10,10,10,10,10,10]},...m}).avg} · ${XP[m.cr].toLocaleString()} XP</small></div><span class="crb">CR ${m.cr}</span>
<div class="bar"><button class="btn sm" data-bv="${i}" aria-expanded="${bOpen===i}">${bOpen===i?'Hide':'View'}</button><button class="btn sm" data-be="${i}">Edit copy</button><button class="btn sm pri" data-ba="${i}">+ Add</button></div></div>${bOpen===i?`<div class="bview"><div class="sb">${sbHTML({...blank(),...m})}</div>${DL?`<button class="btn sm" style="margin-top:10px" data-bp="${i}">Download PDF</button>`:''}</div>`:''}`).join('');
$('#bmore').style.display=L.length>bShown?'':'none'};
['b-q','b-min','b-max','b-type','b-size','b-sort','b-set'].forEach(id=>$('#'+id).addEventListener(id==='b-q'?'input':'change',()=>{bShown=40;bOpen=null;renderBest()}));
$('#bmore').onclick=()=>{bShown+=40;renderBest()};
$('#blist').onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset,list=BL.map(x=>x.m);
if(d.ba){const m=list[+d.ba],f=E.foes.find(x=>x.name===m.name&&x.cr===m.cr);if(f)f.n++;else E.foes.push({name:m.name,cr:m.cr,n:1});renderEncForm();calc();toast(m.name+' joins the fight')}
if(d.bv){bOpen=bOpen===+d.bv?null:+d.bv;renderBest()}
if(d.bp)pdfFor({...blank(),...list[+d.bp]},b);
if(d.be){M={...blank(),...JSON.parse(JSON.stringify(list[+d.be]))};delete M.archiveId;loadForm();location.hash='#monsters';scrollTo({top:0});toast(M.name+' copied into the editor')}};

