$('#rg-locs').innerHTML=Object.entries(LOCS).map(([k,v])=>`<button class="chip" data-loc="${k}">${v}</button>`).join('');
$('#rg-l').innerHTML=Array.from({length:20},(_,k)=>`<option>${k+1}</option>`).join('');
