if(sp.sub.length)c.sub=R(sp.sub).n;if(c.species==='human')c.xskills=[R(SKL.filter(s=>!c.skills.includes(s[0])&&!bg.sk.includes(s[0])))[0]];if(c.species==='elf')c.xskills=[R(['Insight','Perception','Survival'].filter(s=>!c.skills.includes(s)))];
c.expert=shuffle([...c.skills]).slice(0,expertCount(c));buildInv(c);const D=derive(c);if(D.cast){const list=classSpells(cl.i,maxSpellLvl(D));c.spells.can=shuffle(list.filter(s=>!s.l).map(s=>s.n)).slice(0,D.L.can||0);c.spells.prep=shuffle(list.filter(s=>s.l).map(s=>s.n)).slice(0,D.L.prep||0)}
