/* ---------- rules lookup ---------- */
const LCAT=['Spells','Conditions','Weapon Mastery','Weapon Properties','Magic Items','Damage Types','Skills'];
let LK={cat:'Spells',q:'',lvl:'any',cls:'any',sch:'any',conc:false,rit:false,shown:40,open:null};
const fmtRule=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\n+/g,'<br>');
const lkItems=()=>{const q=LK.q.trim().toLowerCase();let L;
if(LK.cat==='Spells'){L=CH.spells.filter(s=>(LK.lvl==='any'||s.l===+LK.lvl)&&(LK.cls==='any'||s.c.includes(LK.cls))&&(LK.sch==='any'||s.sch===LK.sch)&&(!LK.conc||s.co)&&(!LK.rit||s.rit)).map(s=>({n:s.n,sub:`${s.l?`Level ${s.l} ${s.sch}`:`${s.sch} cantrip`}${s.co?' · Concentration':''}${s.rit?' · Ritual':''}`,s,d:s.d}));L.sort((a,b)=>a.s.l-b.s.l||a.n.localeCompare(b.n))}
else if(LK.cat==='Magic Items'){L=[...ITEMS['2024'].map(i=>({...i,c:normCat(i.c)})),...HEAL,...OCOMMON].map(i=>({n:i.n,sub:`${i.c} · ${i.r}${i.a?' · requires attunement':''}${i.src?' · '+i.src:''}`,d:i.d}));L.sort((a,b)=>a.n.localeCompare(b.n))}
else L=(CH.ref[LK.cat]||[]).map(x=>({n:x.n,sub:LK.cat.replace(/s$/,''),d:x.d}));
if(q)L=L.filter(x=>x.n.toLowerCase().includes(q)||x.d.toLowerCase().includes(q)).sort((a,b)=>(b.n.toLowerCase().includes(q))-(a.n.toLowerCase().includes(q)));return L};
const spellBody=s=>`<p class="smeta"><b>Casting time</b> ${esc(s.ct)} · <b>Range</b> ${esc(s.r)} · <b>Components</b> ${esc(s.cmp.split('').join(', '))}${s.mat?` (${esc(s.mat)})`:''} · <b>Duration</b> ${esc(s.du)}</p><p class="smeta"><b>Classes</b> ${s.c.map(c=>cap(c)).join(', ')}</p><p>${fmtRule(s.d)}</p>${s.hl?`<p><b>Using a higher-level spell slot.</b> ${fmtRule(s.hl)}</p>`:''}`;
const lkText=x=>x.s?`${x.n}\n${x.sub}\nCasting time: ${x.s.ct} | Range: ${x.s.r} | Components: ${x.s.cmp}${x.s.mat?' ('+x.s.mat+')':''} | Duration: ${x.s.du}\n${x.s.d.replace(/\*\*/g,'')}${x.s.hl?'\nUsing a higher-level spell slot: '+x.s.hl:''}`:`${x.n} (${x.sub})\n${x.d.replace(/\*\*/g,'')}`;
let LKL=[];
const renderLookup=()=>{document.querySelectorAll('#lk-cats .chip').forEach(b=>b.classList.toggle('on',b.dataset.lc===LK.cat));$('#lk-spf').style.display=LK.cat==='Spells'?'':'none';
LKL=lkItems();$('#lk-count').textContent=`${LKL.length} result${LKL.length===1?'':'s'}`;
$('#lk-list').innerHTML=LKL.length?LKL.slice(0,LK.shown).map((x,i)=>`<div class="lkr${LK.open===i?' open':''}"><button class="lkh" data-lo="${i}" aria-expanded="${LK.open===i}"><span><b>${esc(x.n)}</b><small>${esc(x.sub)}</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button>${LK.open===i?`<div class="lkb">${x.s?spellBody(x.s):`<p>${fmtRule(x.d)}</p>`}<button class="btn sm" data-lcp="${i}">Copy</button></div>`:''}</div>`).join(''):'<p class="muted">Nothing matches. Try a shorter search or clear the filters.</p>';
$('#lk-more').style.display=LKL.length>LK.shown?'':'none'};
$('#lk-cats').innerHTML=LCAT.map(c=>`<button class="chip" data-lc="${c}">${c}</button>`).join('');
$('#lk-lvl').innerHTML='<option value="any">Any level</option><option value="0">Cantrip</option>'+[1,2,3,4,5,6,7,8,9].map(l=>`<option value="${l}">Level ${l}</option>`).join('');
$('#lk-cls').innerHTML='<option value="any">Any class</option>'+CH.classes.filter(c=>c.cast).map(c=>`<option value="${c.i}">${c.n}</option>`).join('');
$('#lk-sch').innerHTML='<option value="any">Any school</option>'+[...new Set(CH.spells.map(s=>s.sch))].sort().map(s=>`<option>${s}</option>`).join('');
$('#lk-cats').onclick=e=>{const b=e.target.closest('[data-lc]');if(!b)return;LK.cat=b.dataset.lc;LK.shown=40;LK.open=null;renderLookup()};
$('#lk-q').addEventListener('input',e=>{LK.q=e.target.value;LK.shown=40;LK.open=null;renderLookup()});
[['lvl','lk-lvl'],['cls','lk-cls'],['sch','lk-sch']].forEach(([k,id])=>$('#'+id).onchange=e=>{LK[k]=e.target.value;LK.shown=40;LK.open=null;renderLookup()});
$('#lk-conc').onchange=e=>{LK.conc=e.target.checked;LK.open=null;renderLookup()};$('#lk-rit').onchange=e=>{LK.rit=e.target.checked;LK.open=null;renderLookup()};
$('#lk-more').onclick=()=>{LK.shown+=40;renderLookup()};
$('#lk-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lo!=null){const i=+b.dataset.lo;LK.open=LK.open===i?null:i;renderLookup()}if(b.dataset.lcp!=null)copy(lkText(LKL[+b.dataset.lcp]),'Copied')});

/* ---------- PDF export ---------- */
let DL=null;
const loadJs=src=>new Promise((res,rej)=>{if(document.querySelector(`script[src="${src}"]`))return res();const el=document.createElement('script');el.src=src;el.onload=res;el.onerror=rej;document.head.appendChild(el)});
const pdfMake=async(html,fname,btn)=>{if(!DL){toast('PDF downloads work on the published site');return}
const lbl=btn.textContent;btn.disabled=true;btn.textContent='Building PDF…';
try{await loadJs('/vendor/html2canvas-1.4.1.min.js');await loadJs('/vendor/jspdf-2.5.1.umd.min.js');
const box=document.createElement('div');box.style.cssText='position:fixed;left:-10000px;top:0;width:720px;background:#fff;padding:24px';
box.innerHTML=`${html}<p style="font:12px Nunito,sans-serif;color:#555;margin:12px 0 0;text-align:center">Created with Smiling DM Studios</p>`;
document.body.appendChild(box);try{await document.fonts.ready}catch(e){}
const c=await html2canvas(box,{scale:2.5,backgroundColor:'#ffffff',logging:false,width:box.offsetWidth,height:box.offsetHeight,windowWidth:box.offsetWidth+40,scrollX:0,scrollY:0});box.remove();
const pdf=new window.jspdf.jsPDF({unit:'pt',format:'letter'}),mg=36,w=612-2*mg,k=w/c.width,per=Math.floor((792-2*mg)/k);
const ah=792-2*mg;if(c.height*k<=ah*1.35){const f=Math.min(1,ah/(c.height*k)),fw=w*f;pdf.addImage(c.toDataURL('image/jpeg',0.92),'JPEG',mg+(w-fw)/2,mg,fw,c.height*k*f)}else
for(let y=0,first=true;y<c.height-4;y+=per,first=false){const h=Math.min(per,c.height-y),pc=document.createElement('canvas');pc.width=c.width;pc.height=h;pc.getContext('2d').drawImage(c,0,y,c.width,h,0,0,c.width,h);if(!first)pdf.addPage();pdf.addImage(pc.toDataURL('image/jpeg',0.92),'JPEG',mg,mg,w,h*k)}
await DL.save({filename:(fname.replace(/[^\w\- '.]+/g,'').trim()||'Download.pdf'),data:pdf.output('blob')});toast('PDF ready')}
catch(err){const c=err&&err.code;if(c==='declined'){}else if(c==='rate_limited')toast('Your download is already starting');else if(c==='unavailable'||c==='not_granted'){DL=null;$('#mpdf').hidden=true;toast('Downloads aren\'t available here')}else toast('Could not build the PDF. Try again.')}
finally{btn.disabled=false;btn.textContent=lbl}};
const pdfFor=(m,btn)=>pdfMake(`<div class="sb" style="box-shadow:none;border-left:1px solid #d9c79a;border-right:1px solid #d9c79a">${sbHTML(m)}</div>`,(m.name||'Monster')+'.pdf',btn);
$('#mpdf').onclick=e=>pdfFor(M,e.currentTarget);
(async()=>{try{if(window.claude&&typeof claude.use==='function'){DL=await claude.use('downloads');if(DL){$('#mpdf').hidden=false;renderBest()}}}catch(e){}})();

/* ---------- shared monster archive ---------- */
let DB=null,ME=null,CANW=null,OWNER=false,archOpen=null;
const setStat=t=>{$('#archStat').textContent=t};
const num=(v,d,lo,hi)=>{v=+v;return Number.isFinite(v)?Math.min(hi,Math.max(lo,Math.round(v))):d};
const str=(v,n=2000)=>typeof v==='string'?v.slice(0,n):'';
const ints=(a,hi)=>Array.isArray(a)?[...new Set(a.map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<=hi))]:[];
const ents=a=>Array.isArray(a)?a.slice(0,30).map(x=>x&&x.atk?{atk:{n:str(x.atk.n,80)||'Attack',k:x.atk.k==='r'?'r':'m',ab:x.atk.ab==='1'||x.atk.ab===1?'1':'0',rg:str(x.atk.rg,40)||'5 ft.',d:/^\d{1,2}d\d{1,3}$/.test(x.atk.d)?x.atk.d:'1d6',t:str(x.atk.t,40)||'bludgeoning'}}:{n:str(x&&x.n,120),d:str(x&&x.d,3000)}):[];
const sanitize=o=>{const b=blank();if(!o||typeof o!=='object')return null;const m={...b,name:str(o.name,80)||'Unnamed Monster',size:sizes.includes(o.size)?o.size:'Medium',type:str(o.type,40)||'Monstrosity',tag:str(o.tag,60),align:str(o.align,60)||'Unaligned',ac:num(o.ac,12,1,30),acNote:str(o.acNote,80),hd:num(o.hd,4,1,99),hdie:[4,6,8,10,12,20].includes(+o.hdie)?+o.hdie:8,speed:str(o.speed,120)||'30 ft.',
ab:Array.isArray(o.ab)&&o.ab.length===6?o.ab.map(x=>num(x,10,1,30)):b.ab,saves:ints(o.saves,5),skills:ints(o.skills,17),expert:ints(o.expert,17),vuln:str(o.vuln,200),res:str(o.res,200),imm:str(o.imm,200),cimm:str(o.cimm,200),senses:str(o.senses,200),langs:str(o.langs,200)||'—',cr:CRS.includes(String(o.cr))?String(o.cr):'1',legN:num(o.legN,0,0,5),
traits:ents(o.traits),actions:ents(o.actions),bonus:ents(o.bonus),reactions:ents(o.reactions),legendary:ents(o.legendary)};
if(o.hpx!=null)m.hpx=num(o.hpx,1,1,9999);m.expert=m.expert.filter(x=>m.skills.includes(x));return m};
const mine=a=>OWNER||(ME&&a.authorId===ME);
const renderArch=()=>{const q=$('#arch-q').value.trim().toLowerCase();const L=ARCH.filter(a=>!q||(a.m.name+' '+a.m.type+' '+(a.by||'')).toLowerCase().includes(q)).sort((x,y)=>(y.updated||0)-(x.updated||0));
if(DB)setStat(ARCH.length?`${ARCH.length} monster${ARCH.length===1?'':'s'} shared by the community${CANW===false?'. You can browse and copy them. Sign in below to share your own.':'.'}`:'The archive is empty. Save a monster to be the first.');
$('#arch').innerHTML=L.slice(0,60).map(a=>`<div><span><b>${esc(a.m.name)}</b> <small class="muted">CR ${esc(a.m.cr)} · by ${esc(a.by||'Anonymous DM')}</small></span><button class="btn sm" data-av="${esc(a.id)}">${archOpen===a.id?'Hide':'View'}</button><button class="btn sm" data-ao="${esc(a.id)}">${mine(a)?'Edit':'Copy'}</button><button class="btn sm" data-af="${esc(a.id)}" aria-label="Add ${esc(a.m.name)} to encounter">+ Fight</button>${mine(a)?`<button class="btn sm x" data-ax="${esc(a.id)}" aria-label="Delete ${esc(a.m.name)} from archive">✕</button>`:''}</div>${archOpen===a.id?`<div class="sb" style="margin:6px 0 10px">${sbHTML(a.m)}</div>${DL?`<button class="btn sm" data-ap="${esc(a.id)}" style="margin-bottom:10px">Download PDF</button>`:''}`:''}`).join('')};
$('#arch-q').addEventListener('input',renderArch);
$('#arch').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset,a=ARCH.find(x=>x.id===(d.av||d.ao||d.af||d.ax||d.ap));if(!a)return;
if(d.ap){pdfFor(a.m,b);return}
if(d.av){archOpen=archOpen===a.id?null:a.id;renderArch()}
if(d.ao){M=JSON.parse(JSON.stringify(a.m));if(mine(a))M.archiveId=a.id;loadForm();scrollTo({top:0});toast(mine(a)?'Editing your archive entry':'Copied into the editor')}
if(d.af){const f=E.foes.find(x=>x.name===a.m.name&&x.cr===a.m.cr);if(f)f.n++;else E.foes.push({name:a.m.name,cr:a.m.cr,n:1});renderEncForm();calc();toast(a.m.name+' added to encounter')}
if(d.ax){try{await DB.collection('archive').doc(a.id).delete();toast('Removed from the archive')}catch(err){toast('Could not delete that entry')}}};
const shareToArchive=async()=>{if(!DB)return'none';if(CANW===false)return'readonly';
const m=sanitize(M);const body={m,by:$('#m-by').value.trim().slice(0,40),authorId:ME||'',updated:Date.now()};
const own=M.archiveId&&ARCH.find(a=>a.id===M.archiveId&&mine(a));const ref=own?DB.collection('archive').doc(M.archiveId):DB.collection('archive').doc();
try{if(own&&ARCH.find(a=>a.id===M.archiveId).authorId)body.authorId=ARCH.find(a=>a.id===M.archiveId).authorId;await ref.set(body);M.archiveId=ref.id;store.set('draft',M);return own?'updated':'ok'}
catch(err){const c=err&&err.code;if(c==='invalid_argument'){CANW=false;renderArch();return'readonly'}if(c==='quota_exceeded')return'full';return'err'}};
$('#m-by').value=store.get('by','');$('#m-by').addEventListener('change',()=>store.set('by',$('#m-by').value.trim()));
(async()=>{try{if(!window.claude||typeof claude.use!=='function'){setStat('The shared archive works on the published site.');return}
const [db,u]=await Promise.all([claude.use('db'),claude.use('user')]);if(!db){setStat('The Monster Archive is coming soon.');return}
DB=db;if(u){try{ME=await u.id()}catch(e){}try{OWNER=!!(await u.isOwner())}catch(e){}try{CANW=await u.can('data.write')}catch(e){}}
setStat('Loading the archive…');const t=setTimeout(()=>setStat('The archive can\'t be reached yet. It will appear when the connection returns.'),10000);
DB.collection('archive').limit(1000).onSnapshot(snap=>{if(!snap.metadata.fromCache)clearTimeout(t);ARCH=snap.docs.map(d=>{const x=d.data()||{};const m=sanitize(x.m);return m?{id:d.id,m,by:str(x.by,40),authorId:str(x.authorId,200),updated:+x.updated||0}:null}).filter(Boolean);renderArch();renderBest()},
err=>{clearTimeout(t);setStat('The archive is unavailable right now.')})}catch(e){setStat('The archive is unavailable right now.')}})();

{const V=document.querySelector('.villain'),HOLD=[[.14,.21],[.38,.475],[.60,.67],[.86,.965]];
if(V&&!matchMedia('(prefers-reduced-motion: reduce)').matches){let last=null;const tick=()=>{const an=V.getAnimations().find(x=>x.animationName==='sneak');if(an&&an.currentTime!=null){const dur=an.effect.getTiming().duration,f=(an.currentTime%dur)/dur,idle=HOLD.some(([x,y])=>f>=x&&f<y);if(idle!==last){V.classList.toggle('idle',idle);last=idle}}requestAnimationFrame(tick)};requestAnimationFrame(tick)}}
